def ev(n):
    if n[0] == 'num':
        return n[1]
    if n[0] == 'add':
        return ev(n[1]) + ev(n[2])
    if n[0] == 'mul':
        return ev(n[1]) * ev(n[2])
tree = ('add', ('num', 2), ('mul', ('num', 3), ('num', 4)))
print(ev(tree))

